   "id": "zd272e15d",
   "sez": "mondo",
   "titolo": "Ripresi i combattimenti a Kherson dopo la fine del cessate il fuoco",
   "orig": "Fighting returns to Kherson region after longest Ukraine war ceasefire",
   "lead": "I combattimenti sono ripresi nella regione di Kherson, in Ucraina, segnando la fine del cessate il fuoco più lungo dall'inizio del conflitto. La tregua, durata sei giorni, è stata considerata un evento senza precedenti, ma non sembra aver modificato in modo significativo l'andamento generale della guerra, che continua a procedere con logoranti scontri sul campo. Nonostante la breve pausa nelle ostilità abbia offerto un momentaneo sollievo, la ripresa degli attacchi conferma la difficoltà di giungere a una soluzione diplomatica duratura tra le parti in causa. Lo riferisce BBC News.",
