   "id": "ze8caf231",
   "sez": "mondo",
   "titolo": "Francia, nuovi blocchi nelle scuole contro il carovita",
   "orig": "French pupils resume school blockades as country braces for more protests",
   "lead": "In Francia, decine di scuole superiori sono state nuovamente bloccate dagli studenti che protestano contro le condizioni del sistema scolastico e l'elevato costo della vita. Il governo si prepara a una settimana di tensioni, mentre i sindacati hanno già indetto uno sciopero nazionale per giovedì. Il ministro dell'Istruzione ha lanciato un avvertimento, sottolineando che le settimane di lezione perse stanno mettendo a serio rischio lo svolgimento degli esami finali per molti alunni. Le mobilitazioni riflettono un diffuso malcontento giovanile che si inserisce in un quadro di agitazioni sociali nel Paese. Lo riferisce The Guardian.",
   "more": [],
