   "id": "z5d202ef4",
   "sez": "prima",
   "titolo": "L'Iran condiziona la riapertura dello stretto di Ormuz a un accordo con gli USA",
   "orig": "Guerra en Irán: Teherán podría reabrir el estrecho de Ormuz en dos días, si Estados Unidos acepta sus condiciones",
   "lead": "L'Iran ha annunciato la possibilità di riaprire lo stretto di Ormuz entro due giorni, a condizione che gli Stati Uniti accettino le richieste di Teheran per porre fine alla tensione militare. Il ministero degli Esteri iraniano ha dichiarato che la decisione finale dipende dalla volontà di Washington, sottolineando che i contatti sono intensi grazie alla mediazione del Qatar. Parallelamente, a Washington, il senatore Marco Rubio ha incontrato il nuovo cancelliere venezuelano Oliver Blanco, segnando un momento di dialogo diplomatico inatteso nel pieno della campagna elettorale statunitense per le elezioni di metà mandato.",
   "more": [
    "Lo stretto di Ormuz è una rotta marittima vitale situata tra il Golfo Persico e il Golfo di Oman. Attraverso questo stretto transita circa un quinto del petrolio consumato a livello globale. La sua chiusura o il blocco parziale hanno effetti immediati sui prezzi internazionali dell'energia e sulla stabilità economica dei mercati mondiali, rendendolo un punto di pressione geopolitica costante."
   ],
