   "titolo": "Tanzania, nuovi posti di lavoro per gli insegnanti laureati in attesa",
   "orig": "Tanzania promises more teaching jobs, prioritises long-waiting graduates",
   "lead": "Il governo della Tanzania ha annunciato un piano per l'assunzione di un maggior numero di insegnanti nell'anno finanziario 2026/27, dando priorità ai laureati che attendono un impiego da più tempo. Anche in altri Paesi africani l'occupazione è al centro delle politiche: il Marocco punta alla sovranità economica nonostante una prevista riduzione delle assunzioni nel settore pubblico, mentre in Ghana i lavoratori attendono una manovra economica focalizzata sulla creazione di posti di lavoro e sull'aumento dei salari per contrastare la disoccupazione e migliorare le condizioni di vita generali. Lo riferisce The Citizen.",
