   "id": "zc2ae3dc8",
   "sez": "salute",
   "titolo": "Approvata la versione generica del farmaco anti-HIV per i paesi poveri",
   "orig": "US approves cheap generic of breakthrough HIV shot for poorer countries",
   "lead": "Le autorità sanitarie degli Stati Uniti hanno approvato la versione generica a basso costo di un farmaco rivoluzionario per la prevenzione dell'HIV, destinata ai Paesi più poveri. L'approvazione del lenacapavir generico, un'iniezione da somministrare due volte l'anno, è stata annunciata dal produttore indiano Dr. Reddy's Laboratories e dall'iniziativa sanitaria globale Unitaid. Questa decisione della FDA rappresenta un passo fondamentale per ampliare l'accesso alle cure in decine di nazioni a basso reddito, permettendo di contrastare la diffusione del virus con un trattamento efficace e sostenibile.",
   "more": [
    "Il lenacapavir è un farmaco antiretrovirale di nuova generazione che agisce inibendo il capside del virus HIV. La sua somministrazione semestrale tramite iniezione rappresenta un enorme vantaggio rispetto alle terapie orali quotidiane, migliorando l'aderenza al trattamento. La disponibilità di versioni generiche è essenziale per le strategie di salute pubblica globale mirate a ridurre drasticamente i contagi."
   ],
