   "titolo": "Kenya: missione AIEA conferma l'impegno sui rifiuti radioattivi",
   "orig": "IAEA Mission Finds Kenya Committed to Safe Management of Radioactive Waste as it Develops a Nuclear Power Programme",
   "lead": "Una missione dell'Agenzia internazionale per l'energia atomica (Aiea) ha rilevato che il Kenya è impegnato nella gestione sicura dei rifiuti radioattivi nell'ambito dello sviluppo del suo programma di energia nucleare. Gli esperti internazionali hanno valutato le infrastrutture e i protocolli di sicurezza del paese africano, riscontrando un approccio responsabile verso la protezione dell'ambiente e della salute pubblica. Il monitoraggio rientra nei piani di assistenza globale dell'agenzia per i paesi che intendono avviare la produzione di energia atomica. Lo riferisce Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "L'AIEA è l'organizzazione intergovernativa che promuove l'uso pacifico dell'energia nucleare e ne impedisce l'utilizzo per scopi militari. Quando un paese decide di sviluppare un programma nucleare civile, deve rispettare rigorosi standard internazionali di sicurezza, specialmente per quanto riguarda lo stoccaggio a lungo termine delle scorie, per prevenire contaminazioni ambientali e rischi sanitari."
   ],
