   "sez": "mondo",
   "titolo": "Israele termina il blocco di Hebron in Cisgiordania",
   "orig": "Jerusalem Daily: Israel’s lockdown of Hebron comes to an end",
   "lead": "Le forze israeliane hanno posto fine al blocco della città di Hebron, nella Cisgiordania occupata, dopo un'operazione militare durata diversi giorni. Nonostante il ritiro delle truppe dall'area urbana, vengono segnalati attacchi persistenti contro una scuola locale. L'esercito aveva inizialmente evacuato i residenti palestinesi in seguito a un attacco nella zona. La fine della chiusura totale permette parzialmente il ripristino della mobilità, ma la situazione sul campo rimane tesa a causa della continua presenza militare nelle aree circostanti. Lo riferisce Al Jazeera.",
   "more": [
    "Hebron è la città più popolosa della Cisgiordania e vive una situazione di tensione costante a causa della divisione in settori controllati dalle autorità israeliane e palestinesi. Le operazioni militari e i blocchi stradali influenzano pesantemente la vita quotidiana, l'economia locale e l'accesso all'istruzione, riflettendo le complessità decennali legate all'occupazione e alla gestione del territorio nel conflitto mediorientale."
   ],
