   "sez": "salute",
   "titolo": "Nuova Zelanda: ritardi critici nelle cure oncologiche",
   "orig": "700 days with a catheter, seven months waiting for 'urgent priority' cancer care",
   "lead": "Un uomo di 82 anni in Nuova Zelanda ha vissuto per 700 giorni con un catetere, aspettando per sette mesi cure oncologiche classificate come \"priorità urgente\". Il paziente riferisce di aver cercato ripetutamente aggiornamenti dall'ospedale di Southland riguardo alla sua operazione, ricevendo però solo mancate risposte a email e messaggi vocali. Parallelamente, negli Stati Uniti, emergono preoccupazioni per l'accessibilità economica delle cure sanitarie, con casi di cliniche d'urgenza che emettono fatture elevate ai pazienti trattandole come prestazioni di pronto soccorso. Lo riferisce RNZ.",
   "more": [
    "I sistemi sanitari pubblici, come quello neozelandese, affrontano spesso sfide legate alle liste d'attesa prolungate dovute a mancanza di personale e risorse. In oncologia, il fattore tempo è determinante per l'efficacia dei trattamenti. Negli Stati Uniti, invece, il sistema è prevalentemente privato e basato su assicurazioni, il che può generare costi imprevisti e molto elevati per i cittadini non adeguatamente coperti."
   ],
