   "sez": "spazio",
   "titolo": "La Cina annuncia un allunaggio umano entro tre anni",
   "orig": "China publicly discloses plan for a lunar landing within three years",
   "lead": "La Cina ha reso pubblico il suo piano per effettuare un allunaggio umano entro i prossimi tre anni. Il programma, che sta procedendo costantemente, prevede una missione di esplorazione lunare con equipaggio, ma non includerà fasi di orbita simili a quelle delle storiche missioni Apollo 8 o dell'imminente Artemis II. L'Agenzia spaziale cinese per il volo umano (CMSA) conferma che lo sviluppo delle tecnologie necessarie per far scendere gli astronauti sulla superficie lunare è in fase avanzata, consolidando le ambizioni spaziali di Pechino. Lo riferisce Ars Technica – Spazio.",
   "more": [
    "L'esplorazione lunare ha visto una nuova accelerazione negli ultimi anni, con diverse nazioni che puntano a stabilire una presenza umana sul satellite. La Cina, attraverso il suo programma spaziale, ha già ottenuto successi significativi con le missioni Chang'e. L'obiettivo dell'allunaggio umano rappresenta una sfida tecnologica enorme per la gestione del supporto vitale e il rientro sicuro degli astronauti sulla Terra."
   ],
