   "titolo": "Funke Akindele racconta il successo e i costi di 'Everybody Loves Jenifa'",
   "orig": "Why ‘Everybody Loves Jenifa’ remains my most expensive film ever – Funke Akindele",
   "lead": "L'attrice e regista di Nollywood Funke Akindele ha spiegato perché \"Everybody Loves Jenifa\" rimane il suo film più costoso di sempre. Riflettendo sulle origini del suo celebre personaggio Jenifa, l'artista ha analizzato il successo commerciale della pellicola, i fallimenti matrimoniali e le lezioni apprese in anni di esposizione mediatica. Akindele sottolinea l'importanza degli investimenti nella qualità produttiva per raggiungere risultati internazionali nell'industria cinematografica nigeriana, nonostante la pressione del giudizio pubblico. Lo riferisce Premium Times.",
   "more": [
    "Nollywood, l'industria cinematografica della Nigeria, è la seconda al mondo per numero di film prodotti annualmente. Funke Akindele è una delle sue figure più iconiche, capace di trasformare personaggi televisivi in fenomeni cinematografici. Il passaggio a produzioni ad alto budget segna un'evoluzione del settore verso standard qualitativi più elevati per attrarre il pubblico globale e le piattaforme di streaming."
   ],
