   "id": "zf21da130",
   "sez": "ingegneria",
   "titolo": "Pigmenti batterici per colorare i tessuti: l'esperimento di Neri Oxman",
   "orig": "Neri Oxman experiments with fabric pigment created by bacteria",
   "lead": "La designer Neri Oxman ha sviluppato un innovativo concetto di tintura dei tessuti che utilizza colture batteriche. Il processo prevede la spruzzatura di una soluzione batterica su una base di seta lavorata a maglia in 3D; durante la crescita, i microrganismi producono pigmenti nelle tonalità dell'indaco e del rosa sfumato. Questa tecnica esplora nuove frontiere della bio-produzione, cercando di sostituire i coloranti chimici tradizionali con alternative biologiche viventi che interagiscono direttamente con la struttura del materiale tessile. Lo riferisce Dezeen.",
   "more": [
    "L'uso di organismi viventi nel design e nell'ingegneria è un campo noto come bio-design. L'obiettivo è creare processi industriali più sostenibili, riducendo l'inquinamento causato dai processi chimici di tintura, che sono tra i più impattanti nel settore tessile. Ricercatori come Neri Oxman studiano come la biologia possa collaborare con la tecnologia per generare materiali autoriparanti o biodegradabili."
   ],
