   "sez": "adolescenti",
   "titolo": "Dimensionamento scolastico 2027/28: approvati i piani regionali",
   "orig": "Dimensionamento scolastico 2027/28: ecco i piani regionali approvati [IN AGGIORNAMENTO]",
   "lead": "Le Regioni e gli Uffici scolastici regionali hanno iniziato a pubblicare i piani di dimensionamento scolastico previsti per l'anno scolastico 2027/28. I documenti, attualmente in fase di aggiornamento, definiscono la riorganizzazione della rete degli istituti sul territorio nazionale, prevedendo accorpamenti e nuove suddivisioni delle sedi. Queste misure sono finalizzate a ottimizzare l'uso delle risorse e a rispondere ai cambiamenti demografici che influenzano il numero di iscritti nelle diverse aree del Paese. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il dimensionamento scolastico è il processo amministrativo con cui lo Stato italiano rivede periodicamente il numero di scuole e la loro distribuzione. L'obiettivo è creare istituti con un numero adeguato di alunni per garantirne l'autonomia e l'efficienza gestionale. Spesso queste decisioni generano dibattito a causa dei possibili disagi per le comunità locali in termini di trasporti e presidi educativi sul territorio."
   ],
