   "sez": "sport",
   "titolo": "Infortunio al collo per Jack Campbell dei Lions: trasportato in ospedale",
   "orig": "Lions shaken after All-Pro linebacker Jack Campbell taken to hospital with ‘scary’ neck injury",
   "lead": "Il linebacker dei Detroit Lions, Jack Campbell, ha riportato un preoccupante infortunio al collo durante il quarto quarto della vittoria della sua squadra contro i Minnesota Vikings. Il giocatore di 26 anni è stato soccorso in campo per circa dieci minuti prima di essere trasportato in un ospedale locale. L'allenatore Dan Campbell ha espresso la sua vicinanza alla famiglia del giocatore, precisando che non sono ancora disponibili informazioni dettagliate sulle sue condizioni, ma assicurando che Campbell è sotto osservazione medica specializzata. Lo riferisce The Guardian.",
   "more": [
    "Il football americano è uno sport ad alto impatto fisico e gli infortuni al collo o alla colonna vertebrale sono tra i più temuti per la loro gravità potenziale. La NFL ha introdotto negli anni rigidi protocolli di sicurezza e soccorso immediato sul campo per minimizzare i rischi di danni permanenti, garantendo il trasporto rapido in centri traumatologici specializzati in caso di traumi cervicali sospetti."
   ],
