   "sez": "economia",
   "titolo": "Gli Stati Uniti escludono Sudafrica e Ruanda dall'accordo commerciale esentasse",
   "orig": "US excludes South Africa, Rwanda from Africa duty-free trade deal",
   "lead": "Gli Stati Uniti hanno deciso di escludere Sudafrica e Ruanda dall'accordo commerciale che permette l'esportazione di merci verso il mercato americano senza il pagamento di dazi. Secondo il rappresentante commerciale Jamieson Greer, le pratiche di entrambi i paesi sono state giudicate incompatibili con i criteri di ammissibilità dell'accordo. La decisione rappresenta un duro colpo per le economie delle due nazioni africane, che perderanno un vantaggio competitivo significativo. Washington utilizza periodicamente queste sospensioni per sollecitare riforme o cambiamenti nelle politiche dei partner commerciali. Lo riferisce The Punch.",
   "more": [
    "L'AGOA (African Growth and Opportunity Act) è un accordo statunitense che consente a molti Paesi dell'Africa subsahariana di esportare prodotti negli Stati Uniti senza dazi. L'accesso è condizionato al rispetto di criteri riguardanti i diritti umani e l'apertura economica. Sospendere un Paese da questo programma significa ridurne la capacità di esportazione, influenzando direttamente i settori produttivi locali."
   ],
