   "sez": "cultura",
   "titolo": "Una mostra a Pristina indaga il significato dell'antifascismo oggi",
   "orig": "Exhibition in Kosovo Capital Asks What Antifascism Means Today",
   "lead": "La capitale del Kosovo, Pristina, ospita la prima tappa fuori dalla Germania della mostra itinerante \"Antifascismo: Ora\". L'esposizione fa parte di una rete decentralizzata che analizza l'eredità storica dell'antifascismo e riflette su quali azioni intraprendere oggi per contrastare la rinascita di ideologie estremiste. Attraverso documenti e opere, la mostra stimola il dibattito pubblico sul ruolo della memoria storica nella società contemporanea e sulla difesa dei valori democratici in un contesto europeo segnato da nuove tensioni. Lo riferisce Prishtina Insight.",
   "more": [
    "Il concetto di antifascismo è nato nel XX secolo come opposizione ai regimi totalitari in Italia e Germania. Oggi, mostre di questo tipo mirano a contestualizzare quel movimento storico rispetto alle sfide dei populismi e dei nazionalismi moderni. Il Kosovo, avendo vissuto conflitti etnici e politici recenti, rappresenta un luogo simbolico per discutere di resistenza alle discriminazioni e promozione della convivenza pacifica."
   ],
