   "id": "z85c6d310",
   "sez": "ingegneria",
   "titolo": "Riciclo creativo: una vecchia poltrona diventa nove oggetti domestici",
   "orig": "discarded leather armchair deconstructs into nine functional domestic objects",
   "lead": "Il designer Jan-Micha Gamer ha dimostrato come una poltrona in pelle destinata ai rifiuti possa essere smontata e riutilizzata per creare nove diversi oggetti funzionali per la casa. Il progetto trasforma i materiali originali in un cesto per il pavimento, un portacandele, una lampada, un portafrutta, un pouf, una cornice, un mobiletto, un tappeto e un tavolino. L'iniziativa esplora le potenzialità del design rigenerativo, invitando a considerare ogni scarto come una risorsa preziosa per la creazione di nuovi complementi d'arredo sostenibili. Lo riferisce Designboom.",
   "more": [
    "L'economia circolare nel design punta a estendere il ciclo di vita dei materiali, riducendo la necessità di nuove materie prime e limitando i rifiuti. Progetti di \"upcycling\" come questo mostrano come la creatività possa risolvere problemi ambientali, trasformando scarti complessi (come le poltrone imbottite) in oggetti semplici e utili, promuovendo una cultura del consumo più responsabile e meno basata sull'usa e getta."
   ],
