   "id": "z328b1c77",
   "sez": "dibattito",
   "titolo": "Riforma degli istituti tecnici, il TAR respinge la sospensiva del decreto",
   "orig": "Riforma istituti tecnici, il TAR boccia lo stop e “salva” il decreto ministeriale. ORDINANZA",
   "lead": "In Italia si discute della riforma dell'istruzione tecnica e professionale a seguito del provvedimento ministeriale che ne prevede la riorganizzazione. Il TAR per il Lazio ha recentemente respinto la richiesta di sospensione d'urgenza avanzata contro il decreto, confermando la validità del percorso avviato dal Ministero. Secondo i sostenitori della riforma, il provvedimento è necessario per modernizzare gli istituti, mentre i ricorrenti esprimono preoccupazioni sull'impatto dei cambiamenti proposti. L'ordinanza del tribunale permette ora di proseguire con l'attuazione delle nuove norme senza subire arresti giudiziari. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La riforma degli istituti tecnici in Italia mira a rafforzare il legame tra istruzione e mondo del lavoro, introducendo modelli formativi più flessibili e orientati alle competenze tecnologiche. Il dibattito si concentra spesso sul rischio di un'eccessiva specializzazione precoce a scapito della formazione culturale generale, e sull'ingresso di figure professionali esterne all'organico scolastico tradizionale per l'insegnamento di materie tecniche specifiche."
   ],
