   "sez": "economia",
   "titolo": "Pakistan, il governo taglia i prezzi di benzina e diesel",
   "orig": "Govt slashes high-speed diesel price by Rs7.76 per litre, petrol by Rs3.40",
   "lead": "Il governo del Pakistan ha annunciato una significativa riduzione dei prezzi del carburante, tagliando il costo del diesel ad alta velocità di 7,76 rupie al litro e quello della benzina di 3,40 rupie. Per contenere l'impatto dei rincari globali dovuti al conflitto in Medio Oriente, le raffinerie nazionali si faranno carico di un onere mensile di circa 15 miliardi di rupie. Questa misura mira a vendere la benzina a un prezzo inferiore rispetto a quello del mercato internazionale, nonostante le tensioni logistiche che hanno visto navi cariche di gas colpite vicino allo Stretto di Hormuz.",
   "more": [
    "Il controllo dei prezzi dell'energia è una priorità politica in Pakistan per prevenire l'inflazione e le tensioni sociali. Poiché il Paese dipende fortemente dalle importazioni, le oscillazioni del mercato globale e le instabilità nelle rotte marittime del Medio Oriente hanno un impatto immediato. Chiedere alle raffinerie di assorbire i costi è una strategia governativa per stabilizzare l'economia interna e proteggere il potere d'acquisto dei cittadini."
   ],
