   "sez": "spazio",
   "titolo": "NASA, pronti al lancio della missione di rifornimento Northrop Grumman CRS-25",
   "orig": "NASA Invites Media to Northrop Grumman CRS-25 Station Resupply Launch",
   "lead": "La NASA ha aperto le procedure di accreditamento per i media in vista del lancio della missione Northrop Grumman CRS-25, previsto per novembre. Un veicolo spaziale Cygnus XL sarà lanciato verso la Stazione Spaziale Internazionale a bordo di un razzo Falcon 9 di SpaceX da Cape Canaveral. La missione ha l'obiettivo di consegnare rifornimenti vitali, attrezzature scientifiche e nuovi esperimenti al laboratorio orbitale. Questo lancio rappresenta un ulteriore passo nella collaborazione tra la NASA e i partner privati per garantire il supporto logistico continuo agli astronauti nello spazio. Lo riferisce Nasa.",
   "more": [
    "Le missioni di rifornimento commerciale (CRS) sono essenziali per il funzionamento della Stazione Spaziale Internazionale. Senza questi voli regolari, gli astronauti non avrebbero accesso a cibo, acqua e strumenti necessari per le attività di ricerca. La diversificazione dei lanciatori, come l'uso del razzo Falcon 9 per trasportare la capsula Cygnus, aumenta la flessibilità e l'affidabilità del sistema di trasporto spaziale globale."
   ],
