   "sez": "salute",
   "titolo": "Inghilterra, oltre 3.000 bambini ricoverati per varicella nell'ultimo anno",
   "orig": "Chickenpox: Over 3000 children were admitted to hospital in England last year",
   "lead": "Oltre 3.000 bambini sotto i 18 anni sono stati ricoverati in ospedale per varicella in Inghilterra lo scorso anno, secondo i nuovi dati della UK Health Security Agency. I bambini di età pari o inferiore a 5 anni sono stati i più colpiti, rappresentando oltre il 70% dei casi segnalati nel 2025. I tassi di ospedalizzazione più elevati sono stati registrati tra i neonati sotto l'anno di età. Le autorità sanitarie monitorano con attenzione questi dati per valutare l'impatto della malattia e l'efficacia delle attuali politiche vaccinali e di prevenzione pediatrica a livello nazionale. Lo riferisce The BMJ.",
   "more": [
    "La varicella è una malattia esantematica comune nell'infanzia, generalmente considerata lieve ma che può causare complicazioni gravi richiedendo il ricovero, specialmente nei soggetti molto piccoli. In molti Paesi il vaccino è raccomandato per ridurre la circolazione del virus e prevenire le forme severe, proteggendo la popolazione pediatrica e diminuendo significativamente il carico sul sistema ospedaliero nazionale."
   ],
