   "sez": "cultura",
   "titolo": "Torna il festival della street art a Lagos",
   "orig": "Lagos art festival returns, promotes public creativity",
   "lead": "La seconda edizione del Lagos Street Art Festival è pronta a partire in Nigeria con un programma dedicato all'espansione dell'arte pubblica e dell'espressione creativa nella metropoli. L'evento mira a promuovere la creatività collettiva e a rafforzare il ruolo delle opere artistiche negli spazi urbani, offrendo una piattaforma per gli artisti locali e internazionali. L'iniziativa si propone di trasformare il volto della città attraverso interventi visivi che coinvolgano direttamente la comunità, promuovendo il valore sociale della creatività. Lo riferisce The Punch.",
   "more": [
    "La street art è una forma di espressione artistica che si manifesta in luoghi pubblici, spesso utilizzando tecniche come il muralismo o i graffiti. Oltre al valore estetico, queste manifestazioni possono favorire la riqualificazione urbana e stimolare il dialogo sociale, trasformando muri anonimi in strumenti di comunicazione e identità culturale per i residenti delle grandi aree metropolitane."
   ],
