   "sez": "cultura",
   "titolo": "Ellis King esplora l'esperienza femminile a Londra",
   "orig": "Discover Ellis King, the artist making sense of women's experiences",
   "lead": "La galleria SQFT: Space di Londra ospita la mostra \"Spilt Milk\" dell'artista Ellis King. L'esposizione si concentra sull'indagine dei momenti di quiete e dell'intimità quotidiana delle donne, cercando di dare un senso alle loro esperienze personali attraverso la produzione artistica. L'opera di King invita il pubblico a riflettere sulla dimensione privata e sulle sfumature della vita femminile contemporanea nel contesto della capitale britannica, esplorando ciò che accade nei momenti di silenzio. Lo riferisce Wallpaper*.",
   "more": [
    "Le gallerie d'arte contemporanea svolgono un ruolo fondamentale nel promuovere artisti emergenti e nell'offrire spazi di riflessione su temi sociali e identitari. Londra è uno dei principali centri mondiali per il mercato dell'arte, ospitando numerose istituzioni che facilitano il dialogo tra creatività individuale e pubblico internazionale, influenzando le tendenze estetiche globali."
   ],
