   "id": "zed56655e",
   "sez": "dibattito",
   "titolo": "D’Alema critica la gestione dell'ordine pubblico di fronte alle proteste giovanili",
   "orig": "D’Alema a La7: “I ragazzi protestano contro i disvalori della destra di governo. Ridurre tutto a ordine pubblico è povertà culturale, umana e politica”",
   "lead": "Massimo D’Alema, intervenendo alla trasmissione \"In Onda\" su La7, ha espresso il suo sostegno ai giovani che manifestano contro le politiche del governo. Secondo l'ex presidente del Consiglio, vedere le piazze piene di ragazzi è un segnale positivo di reazione al conformismo e ai disvalori della destra. D'Alema sostiene che ridurre queste proteste a una semplice questione di ordine pubblico rappresenti una povertà culturale e politica, poiché i manifestanti reagirebbero a una regressione sociale guidata dall'esecutivo. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "In Italia si discute della gestione delle proteste studentesche e del ruolo del dissenso giovanile. Massimo D'Alema sostiene che le manifestazioni siano una risposta ai valori del governo e critica la riduzione del tema a mero ordine pubblico. Di contro, i sostenitori della linea governativa pongono l'accento sulla necessità di garantire la legalità e la sicurezza pubblica durante i blocchi, evidenziando il dovere delle istituzioni di mantenere la stabilità sociale."
   ],
