   "sez": "tech",
   "titolo": "Classifica dei 15 smartphone con i più alti livelli di radiazioni",
   "orig": "Top 15 telefoane după cel mai ridicat nivel de radiații emise. Cum s-au făcut măsurătorile",
   "lead": "Visual Capitalist ha stilato una lista dei 15 modelli di smartphone più popolari basata sul livello di radiazioni emesse durante il loro utilizzo. La ricerca evidenzia come ogni dispositivo utilizzi onde radio per comunicare con le reti, ma la quantità di energia assorbita dall'utente vari sensibilmente tra i diversi modelli. I dati mostrano le discrepanze tra i dispositivi più diffusi sul mercato, analizzando i parametri di assorbimento specifici per ciascuno smartphone testato per informare i consumatori. Lo riferisce HotNews.",
   "more": [
    "Il tasso di assorbimento specifico (SAR) misura la quantità di energia a radiofrequenza assorbita dal corpo umano quando si utilizza un telefono cellulare. Gli organismi di regolamentazione internazionali stabiliscono limiti di sicurezza rigorosi per questi valori, al fine di garantire che l'esposizione alle onde elettromagnetiche non superi i livelli ritenuti sicuri per la salute pubblica."
   ],
