   "titolo": "Il giardino del museo Hirshhorn rinnovato da Hiroshi Sugimoto",
   "orig": "The Hirshhorn's Brutalist sculpture garden just got a makeover, thanks to photographer and architect Hiroshi Sugimoto",
   "lead": "Il giardino delle sculture brutaliste del Museo Hirshhorn di Washington è stato restaurato sotto la direzione dell'architetto Hiroshi Sugimoto. L'istituto d'arte modernista, originariamente progettato da Gordon Bunshaft, è stato rinnovato con un approccio conservativo che ha permesso l'inserimento di decine di nuove opere d'arte. L'intervento mira a rivitalizzare lo spazio espositivo all'aperto, integrando la visione architettonica originale con nuove sensibilità estetiche e funzionali per accogliere i visitatori nella capitale statunitense. Lo riferisce Wallpaper*.",
   "more": [
    "Il brutalismo è un movimento architettonico caratterizzato dall'uso del cemento a vista e da forme geometriche massicce. Il restauro di edifici e spazi pubblici di questo periodo richiede un equilibrio tra la preservazione delle caratteristiche storiche e l'adeguamento alle esigenze contemporanee, rendendo gli spazi più accessibili e integrati con il paesaggio urbano circostante."
   ],
