   "sez": "dibattito",
   "titolo": "Sciopero al liceo Paul Éluard di Saint-Denis contro il preside",
   "orig": "Au lycée Paul Éluard de Saint-Denis, le personnel en grève réclame le départ du proviseur",
   "lead": "Il personale del liceo Paul Éluard di Saint-Denis, in Francia, è entrato in sciopero per chiedere le dimissioni del preside. I manifestanti esigono inoltre la garanzia che non vengano applicate sanzioni disciplinari contro i dipendenti e gli studenti che hanno preso parte alle recenti proteste e ai blocchi dell'istituto. La mobilitazione evidenzia un clima di forte tensione tra la direzione e la comunità scolastica riguardo alla gestione delle attività didattiche e alla libertà di manifestazione. Lo riferisce Le Figaro.",
   "more": [
    "In Francia si discute dell'autonomia scolastica e del limite tra diritto di sciopero e interruzione di pubblico servizio. Il personale del liceo Paul Éluard chiede la rimozione del dirigente e l'annullamento delle sanzioni per chi ha partecipato ai blocchi, sostenendo il valore della protesta. Di contro, l'amministrazione scolastica pone l'accento sulla necessità di garantire il diritto allo studio e la sicurezza negli edifici scolastici."
   ],
