   "titolo": "Uno studio avverte sui limiti del polo tecnologico Pax Silica nelle Filippine",
   "orig": "Attracting tech giants to Pax Silica not enough, UP study warns",
   "lead": "Secondo uno studio dell'Università delle Filippine, attirare colossi del tech come Apple e Nvidia nel nuovo hub Pax Silica potrebbe non essere sufficiente a far avanzare il Paese verso i settori a più alto valore della produzione di semiconduttori. Nonostante il progetto sia sostenuto dagli Stati Uniti, la ricerca suggerisce che la semplice presenza di multinazionali non garantisce automaticamente un salto tecnologico per l'industria locale. Il governo filippino ha identificato diverse aziende chiave, ma resta la sfida di integrare profondamente l'economia nazionale in segmenti tecnologici più complessi. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "L'industria dei semiconduttori è una delle più strategiche a livello globale e le Filippine rappresentano tradizionalmente un polo importante per le fasi di test e assemblaggio. Spostarsi verso il design e la fabbricazione di chip richiede ingenti investimenti in ricerca e formazione specialistica, oltre a politiche industriali capaci di favorire il trasferimento tecnologico dalle multinazionali alle imprese locali."
   ],
