   "id": "zd62ce13b",
   "sez": "salute",
   "titolo": "Studio sui topi mette in dubbio i benefici a lungo termine della psilocibina",
   "orig": "STAT+: Psilocybin’s lasting benefits prove elusive in mice",
   "lead": "Una collaborazione tra cinque laboratori ha testato gli effetti duraturi della psilocibina su ansia e depressione nei topi, ottenendo risultati molto limitati. Lo studio suggerisce che i benefici a lungo termine osservati in precedenza potrebbero non essere così solidi come ipotizzato. La ricerca evidenzia la difficoltà di replicare in modo costante i miglioramenti comportamentali legati all'uso di questa sostanza psichedelica, invitando a una maggiore cautela nell'interpretazione dei dati scientifici riguardanti le sue potenzialità terapeutiche per i disturbi della salute mentale. Lo riferisce STAT.",
   "more": [
    "La psilocibina è un composto psichedelico presente in alcuni funghi ed è oggetto di numerosi studi clinici per il trattamento della depressione. Sebbene alcuni test sull'uomo abbiano mostrato risultati promettenti, la ricerca di base sugli animali è fondamentale per comprenderne i meccanismi d'azione biochimici e i possibili limiti sul lungo periodo prima di un eventuale utilizzo medico controllato."
   ],
