   "sez": "tech",
   "titolo": "Immagini inedite di un drone che affonda una petroliera greca nel Mar Nero",
   "orig": "Watch: Unseen images of drone sinking Greek tanker off Bulgarian coast",
   "lead": "Sono state diffuse immagini inedite che mostrano un attacco condotto da un drone contro una petroliera greca al largo delle coste bulgare. La Russia è la principale sospettata per questa ondata di attacchi mirati contro le navi commerciali che operano nel Mar Nero. L'incidente evidenzia l'escalation dell'uso di tecnologie autonome nel conflitto regionale per colpire infrastrutture civili e navi da trasporto, mettendo a grave rischio la sicurezza dei traffici marittimi internazionali e la stabilità dell'area bulgara. Lo riferisce Euronews.",
   "more": [
    "Il Mar Nero è un'area di vitale importanza strategica per l'esportazione di energia e materie prime, ma è diventato un teatro di guerra instabile. L'impiego di droni marini e aerei ha cambiato radicalmente la natura dei conflitti marittimi, rendendo le navi mercantili vulnerabili ad attacchi difficili da prevedere senza scorte militari costanti o sistemi di difesa elettronica avanzati."
   ],
